1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"math/big"
10		"regexp"
11		"sort"
12		"strconv"
13		"strings"
14		"unicode"
15		"unicode/utf16"
16		"unicode/utf8"
17	)
18	
19	// Point 是一条序列上某个时间戳的采样值。
20	type Point struct {
21		Timestamp int64   `json:"timestamp"`
22		Value     float64 `json:"value"`
23	}
24	
25	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
26	type SeriesView struct {
27		Name   string            `json:"name"`
28		Labels map[string]string `json:"labels"`
29		Points []Point           `json:"points"`
30	}
31	
32	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
33	type QuerySeries struct {
34		Name    string            `json:"name"`
35		Labels  map[string]string `json:"labels"`
36		Count   int               `json:"count"`
37		Average float64           `json:"average"`
38	}
39	
40	// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
41	type QueryResult struct {
42		Status string        `json:"status"`
43		Op     string        `json:"op"`
44		Series []QuerySeries `json:"series"`
45	}
46	
47	// QueryPointsSeries 是采样明细查询结果中的一条序列：完整身份与区间内
48	// 按时间戳升序排列的采样点，不附带点数或平均值。
49	type QueryPointsSeries struct {
50		Name   string            `json:"name"`
51		Labels map[string]string `json:"labels"`
52		Points []Point           `json:"points"`
53	}
54	
55	// QueryPointsResult 是一次区间采样明细查询（op 为 query_points）成功后的结果，
56	// 只读，不改变存储。
57	type QueryPointsResult struct {
58		Status string              `json:"status"`
59		Op     string              `json:"op"`
60		Series []QueryPointsSeries `json:"series"`
61	}
62	
63	// BatchResult 是一批采样点写入成功后的结果。
64	type BatchResult struct {
65		Status     string       `json:"status"`
66		Added      int          `json:"added"`
67		Duplicates int          `json:"duplicates"`
68		Series     []SeriesView `json:"series"`
69	}
70	
71	// SeriesRef 标识一条序列：指标名加完整标签集合。
72	// 缺少某个标签与该标签值为空字符串属于不同序列。
73	type SeriesRef struct {
74		Name   string            `json:"name"`
75		Labels map[string]string `json:"labels"`
76	}
77	
78	// Conflict 描述同一序列同一时间戳已存在不同的值。
79	type Conflict struct {
80		Series    SeriesRef `json:"series"`
81		Timestamp int64     `json:"timestamp"`
82		Existing  float64   `json:"existing"`
83		Submitted float64   `json:"submitted"`
84	}
85	
86	// LineError 是一行（一批）输入失败后的结构化结果。
87	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
88	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
89	type LineError struct {
90		Status   string    `json:"status"`
91		Line     int       `json:"line,omitempty"`
92		Index    int       `json:"index,omitempty"`
93		Error    string    `json:"error"`
94		Conflict *Conflict `json:"conflict,omitempty"`
95	}
96	
97	// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
98	type MetricStore struct {
99		series map[seriesID]*storedSeries
100	}
101	
102	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
103	type seriesID struct {
104		name string
105		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
106		sig string
107	}
108	
109	type storedSeries struct {
110		ref    SeriesRef
111		points map[int64]float64
112	}
113	
114	// NewMetricStore 创建一个空的指标存储。
115	func NewMetricStore() *MetricStore {
116		return &MetricStore{series: make(map[seriesID]*storedSeries)}
117	}
118	
119	// cloneLabels 返回标签集合的独立副本；空标签仍复制为非 nil 的空集合，
120	// 调用方对副本的增删改不影响存储中的序列身份。
121	func cloneLabels(labels map[string]string) map[string]string {
122		out := make(map[string]string, len(labels))
123		for k, v := range labels {
124			out[k] = v
125		}
126		return out
127	}
128	
129	func sortedKeys(m map[string]string) []string {
130		keys := make([]string, 0, len(m))
131		for k := range m {
132			keys = append(keys, k)
133		}
134		sort.Strings(keys)
135		return keys
136	}
137	
138	func makeSeriesID(name string, labels map[string]string) seriesID {
139		var b strings.Builder
140		for _, k := range sortedKeys(labels) {
141			v := labels[k]
142			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
143		}
144		return seriesID{name: name, sig: b.String()}
145	}
146	
147	// labelPair 是标签键值对字典序比较的单元。
148	type labelPair struct {
149		Key, Value string
150	}
151	
152	func sortedPairs(labels map[string]string) []labelPair {
153		keys := sortedKeys(labels)
154		pairs := make([]labelPair, len(keys))
155		for i, k := range keys {
156			pairs[i] = labelPair{Key: k, Value: labels[k]}
157		}
158		return pairs
159	}
160	
161	func compareLabelPairs(a, b []labelPair) int {
162		n := len(a)
163		if len(b) < n {
164			n = len(b)
165		}
166		for i := 0; i < n; i++ {
167			if a[i].Key != b[i].Key {
168				return strings.Compare(a[i].Key, b[i].Key)
169			}
170			if a[i].Value != b[i].Value {
171				return strings.Compare(a[i].Value, b[i].Value)
172			}
173		}
174		switch {
175		case len(a) < len(b):
176			return -1
177		case len(a) > len(b):
178			return 1
179		}
180		return 0
181	}
182	
183	var (
184		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
185		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
186	)
187	
188	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
189	// 成功时返回非 nil 的 *BatchResult、*QueryResult 或 *QueryPointsResult 且错误为
190	// nil；任何失败都返回真正的 nil 结果与 *LineError，调用方直接比较
191	// result == nil 即可判定失败，无须先区分结果类型。空写入数组与无命中的查询
192	// 仍是成功，结果不为 nil。
193	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
194		top, ok, lerr := decodeTopValue(line)
195		if lerr != nil {
196			return nil, lerr
197		}
198		switch ok {
199		case '[':
200			var items []json.RawMessage
201			if err := json.Unmarshal(top, &items); err != nil {
202				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
203			}
204			// 不能把 *BatchResult 直接装进 any 返回：失败时它是带类型的 nil 指针，
205			// 接口值非 nil，调用方会把失败误判为有结果。
206			batch, lerr := s.ingestItems(items)
207			if lerr != nil {
208				return nil, lerr
209			}
210			return batch, nil
211		case '{':
212			// 同上：失败时不能把带类型 nil 的结果指针装进 any。
213			return s.queryFromObject(top)
214		default:
215			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
216		}
217	}
218	
219	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
220	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
221	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
222		top, ok, lerr := decodeTopValue(line)
223		if lerr != nil {
224			return nil, lerr
225		}
226		if ok != '[' {
227			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
228		}
229		var items []json.RawMessage
230		if err := json.Unmarshal(top, &items); err != nil {
231			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
232		}
233		return s.ingestItems(items)
234	}
235	
236	// QueryLine 解析并执行一行 op 为 "query" 的区间均值查询对象。成功返回 QueryResult；
237	// 查询只读，不改变存储。op 为 "query_points" 的采样明细查询由 QueryPointsLine 执行。
238	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
239		top, ok, lerr := decodeTopValue(line)
240		if lerr != nil {
241			return nil, lerr
242		}
243		if ok != '{' {
244			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
245		}
246		res, lerr := s.queryFromObject(top)
247		if lerr != nil {
248			return nil, lerr
249		}
250		qr, isQuery := res.(*QueryResult)
251		if !isQuery {
252			return nil, &LineError{Status: "error", Error: `op "query_points" lists sample points; use QueryPointsLine`}
253		}
254		return qr, nil
255	}
256	
257	// QueryPointsLine 解析并执行一行 op 为 "query_points" 的区间采样明细查询对象。
258	// 成功返回 QueryPointsResult；查询只读，不改变存储。
259	func (s *MetricStore) QueryPointsLine(line string) (*QueryPointsResult, *LineError) {
260		top, ok, lerr := decodeTopValue(line)
261		if lerr != nil {
262			return nil, lerr
263		}
264		if ok != '{' {
265			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
266		}
267		res, lerr := s.queryFromObject(top)
268		if lerr != nil {
269			return nil, lerr
270		}
271		qp, isPoints := res.(*QueryPointsResult)
272		if !isPoints {
273			return nil, &LineError{Status: "error", Error: `op "query" computes range statistics; use QueryLine`}
274		}
275		return qp, nil
276	}
277	
278	// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
279	// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
280	// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
281	// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
282	//
283	// 逐字节扫描、只在字符串内部识别转义：跳过词法空白与全部非字符串 token。
284	// 被转义的反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成 Unicode 转义。
285	func validateLineText(line string) *LineError {
286		if !utf8.ValidString(line) {
287			return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
288		}
289		inString := false
290		for i := 0; i < len(line); i++ {
291			c := line[i]
292			if !inString {
293				if c == '"' {
294					inString = true
295				}
296				continue
297			}
298			switch c {
299			case '"':
300				inString = false
301			case '\\':
302				if i+1 >= len(line) {
303					break // 悬空反斜杠：交给 JSON 解析器报错
304				}
305				if line[i+1] != 'u' {
306					i++ // 单字符转义（\\、\"、\n 等），跳过被转义字符
307					continue
308				}
309				// i 指向 '\'，i+1 指向 'u'；转义占据 i..i+5。
310				r, size := decodeJSONHexEscape(line, i+1)
311				if size == 0 {
312					return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
313				}
314				if !utf16.IsSurrogate(r) {
315					i += 5
316					continue
317				}
318				if r >= 0xDC00 {
319					// 单独出现的低代理项。
320					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
321				}
322				// 高代理项后必须紧接另一个表示低代理项的 \uXXXX 转义。
323				loPos := i + 6 // 第一个转义之后的字符位置
324				if loPos+1 >= len(line) || line[loPos] != '\\' || line[loPos+1] != 'u' {
325					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
326				}
327				lo, loSize := decodeJSONHexEscape(line, loPos+1)
328				if loSize == 0 || lo < 0xDC00 || lo > 0xDFFF {
329					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
330				}
331				i = loPos + loSize // 跳到第二转义的最后一个十六进制位，循环自增后越出
332			}
333		}
334		return nil
335	}
336	
337	// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
338	// 返回其码元与占用字节数（固定为 5）；不足四个十六进制数字时 size 为 0。
339	func decodeJSONHexEscape(line string, pos int) (rune, int) {
340		if pos+4 >= len(line) {
341			return 0, 0
342		}
343		var v rune
344		for j := pos + 1; j <= pos+4; j++ {
345			c := line[j]
346			var d rune
347			switch {
348			case c >= '0' && c <= '9':
349				d = rune(c - '0')
350			case c >= 'a' && c <= 'f':
351				d = rune(c-'a') + 10
352			case c >= 'A' && c <= 'F':
353				d = rune(c-'A') + 10
354			default:
355				return 0, 0
356			}
357			v = v<<4 | d
358		}
359		return v, 5
360	}
361	
362	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
363	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
364	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
365		if lerr := validateLineText(line); lerr != nil {
366			return nil, 0, lerr
367		}
368		dec := json.NewDecoder(strings.NewReader(line))
369		var top json.RawMessage
370		if err := dec.Decode(&top); err != nil {
371			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
372		}
373		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
374		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
375			if err == nil {
376				err = fmt.Errorf("unexpected content after the JSON value")
377			}
378			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
379		}
380		trimmed := strings.TrimSpace(string(top))
381		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
382			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
383		}
384		return top, trimmed[0], nil
385	}
386	
387	// fieldReader 从 dec 读取并校验当前字段的值，写入调用方持有的结果。
388	// 采样点与查询对象各自注册自己允许的字段及字段含义。
389	type fieldReader func(dec *json.Decoder) error
390	
391	// parseStrictObject 是写入采样点与查询对象共用的严格对象校验骨架：
392	// 仅允许 fields 中列出的字段（未知字段先于判重被拒绝），同一对象内按转义还原
393	// 后的字段名判重（即使两个值相同也拒绝；判重不跨对象、不跨层级），按输入次序
394	// 逐字段调用对应的 fieldReader，对象结束后要求输入恰好耗尽，最后按 required
395	// 的顺序报告缺失的必填字段。notObjectMsg 与 trailingMsg 由调用方给出，
396	// 保留各自输入的措辞。
397	func parseStrictObject(raw json.RawMessage, notObjectMsg, trailingMsg string, required []string, fields map[string]fieldReader) error {
398		dec := json.NewDecoder(bytes.NewReader(raw))
399		dec.UseNumber()
400	
401		tok, err := dec.Token()
402		if err != nil {
403			return err
404		}
405		if d, ok := tok.(json.Delim); !ok || d != '{' {
406			return fmt.Errorf("%s", notObjectMsg)
407		}
408	
409		present := make(map[string]bool)
410		for dec.More() {
411			keyTok, err := dec.Token()
412			if err != nil {
413				return err
414			}
415			key := keyTok.(string)
416			read, ok := fields[key]
417			if !ok {
418				return fmt.Errorf("unknown field %q", key)
419			}
420			if present[key] {
421				return fmt.Errorf("duplicate field %q", key)
422			}
423			present[key] = true
424			if err := read(dec); err != nil {
425				return err
426			}
427		}
428		if _, err := dec.Token(); err != nil { // 消耗 '}'
429			return err
430		}
431		if _, err := dec.Token(); err != io.EOF {
432			if err == nil {
433				return fmt.Errorf("%s", trailingMsg)
434			}
435			return err
436		}
437	
438		for _, field := range required {
439			if !present[field] {
440				return fmt.Errorf("missing required field %q", field)
441			}
442		}
443		return nil
444	}
445	
446	// readNameField 读取写入与查询共用的指标名字段：必须是非空字符串。
447	func readNameField(dec *json.Decoder, dst *string) error {
448		t, err := dec.Token()
449		if err != nil {
450			return err
451		}
452		s, ok := t.(string)
453		if !ok {
454			return fmt.Errorf(`field "name" must be a string`)
455		}
456		if s == "" {
457			return fmt.Errorf(`field "name" must be a non-empty string`)
458		}
459		*dst = s
460		return nil
461	}
462	
463	// readInt64Field 读取 int64 毫秒整数字段（timestamp/start/end）：
464	// 必须是 JSON 整数且在 int64 范围内，数字字符串、布尔值、带小数点一律拒绝。
465	func readInt64Field(dec *json.Decoder, field string, dst *int64) error {
466		n, err := nextJSONNumber(dec, field)
467		if err != nil {
468			return err
469		}
470		v, err := parseJSONInt(n)
471		if err != nil {
472			return fmt.Errorf("field %q: %s", field, err)
473		}
474		*dst = v
475		return nil
476	}
477	
478	// readFiniteFloatField 读取采样值字段：必须是可表示为有限 float64 的 JSON 数字。
479	func readFiniteFloatField(dec *json.Decoder, field string, dst *float64) error {
480		n, err := nextJSONNumber(dec, field)
481		if err != nil {
482			return err
483		}
484		v, err := parseFiniteFloat(n)
485		if err != nil {
486			return fmt.Errorf("field %q: %s", field, err)
487		}
488		*dst = v
489		return nil
490	}
491	
492	// readLabelsField 读取标签对象字段并写入 dst；notObjectMsg 保留各输入侧措辞。
493	func readLabelsField(dec *json.Decoder, notObjectMsg string, dst *map[string]string) error {
494		labels, err := parseLabels(dec, notObjectMsg)
495		if err != nil {
496			return err
497		}
498		*dst = labels
499		return nil
500	}
501	
502	type parsedSample struct {
503		name   string
504		ts     int64
505		value  float64
506		labels map[string]string
507	}
508	
509	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
510	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
511	func parseSample(raw json.RawMessage) (parsedSample, error) {
512		var p parsedSample
513		p.labels = map[string]string{}
514		err := parseStrictObject(raw,
515			"each sample must be a JSON object",
516			"unexpected content after the sample object",
517			[]string{"name", "timestamp", "value"},
518			map[string]fieldReader{
519				"name":      func(dec *json.Decoder) error { return readNameField(dec, &p.name) },
520				"timestamp": func(dec *json.Decoder) error { return readInt64Field(dec, "timestamp", &p.ts) },
521				"value":     func(dec *json.Decoder) error { return readFiniteFloatField(dec, "value", &p.value) },
522				"labels": func(dec *json.Decoder) error {
523					return readLabelsField(dec, `field "labels" must be an object of string keys to string values`, &p.labels)
524				},
525			})
526		return p, err
527	}
528	
529	// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
530	// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
531	// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
532	// 判重先于值的类型校验：某个键第一次出现时若值不是字符串，仍报告该值的类型
533	// 错误；而该键再次出现时，无论第二次的值是什么（数字、布尔、null、对象、数组），
534	// 都先报告重复标签键，不能让第二次值的类型掩盖键重复。
535	// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
536	func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
537		t, err := dec.Token()
538		if err != nil {
539			return nil, err
540		}
541		d, ok := t.(json.Delim)
542		if !ok || d != '{' {
543			return nil, fmt.Errorf("%s", notObjectMsg)
544		}
545		labels := map[string]string{}
546		for dec.More() {
547			labelKeyTok, err := dec.Token()
548			if err != nil {
549				return nil, err
550			}
551			labelKey := labelKeyTok.(string)
552			if labelKey == "" {
553				return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
554			}
555			// 先判重再读值：与采样点/查询字段的判重一致，重复键不被值的类型掩盖。
556			if _, dup := labels[labelKey]; dup {
557				return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
558			}
559			valTok, err := dec.Token()
560			if err != nil {
561				return nil, err
562			}
563			labelVal, ok := valTok.(string)
564			if !ok {
565				return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
566			}
567			labels[labelKey] = labelVal
568		}
569		if _, err := dec.Token(); err != nil { // 消耗 '}'
570			return nil, err
571		}
572		return labels, nil
573	}
574	
575	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
576		t, err := dec.Token()
577		if err != nil {
578			return "", err
579		}
580		n, ok := t.(json.Number)
581		if !ok {
582			return "", fmt.Errorf(`field %q must be a JSON number`, field)
583		}
584		return n, nil
585	}
586	
587	func parseJSONInt(n json.Number) (int64, error) {
588		s := string(n)
589		if !jsonIntegerRE.MatchString(s) {
590			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
591		}
592		v, err := strconv.ParseInt(s, 10, 64)
593		if err != nil {
594			return 0, fmt.Errorf("must be within int64 range")
595		}
596		return v, nil
597	}
598	
599	func parseFiniteFloat(n json.Number) (float64, error) {
600		s := string(n)
601		if !jsonNumberRE.MatchString(s) {
602			return 0, fmt.Errorf("must be a JSON number")
603		}
604		v, err := strconv.ParseFloat(s, 64)
605		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
606			return 0, fmt.Errorf("must be a finite number representable as float64")
607		}
608		return v, nil
609	}
