611	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
612	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
613		type pending struct {
614			id  seriesID
615			ref SeriesRef
616			ts  int64
617			val float64
618		}
619	
620		added := 0
621		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
622		seen := make(map[seriesID]map[int64]float64)
623		// 仅记录需要落盘的新增点；校验全部通过后才提交。
624		commits := make([]pending, 0, len(items))
625	
626		failAt := func(index int, msg string) *LineError {
627			return &LineError{Status: "error", Index: index, Error: msg}
628		}
629		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
630			return &LineError{
631				Status: "error",
632				Index:  index,
633				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
634					ref, ts, formatFloat(existing), formatFloat(submitted)),
635				Conflict: &Conflict{
636					// 标签必须复制：冲突结果是本次失败的独立记录，
637					// 调用方修改它不能改动已存序列的身份。
638					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
639					Timestamp: ts,
640					Existing:  existing,
641					Submitted: submitted,
642				},
643			}
644		}
645	
646		for i, item := range items {
647			pos := i + 1
648			p, err := parseSample(item)
649			if err != nil {
650				return nil, failAt(pos, err.Error())
651			}
652	
653			id := makeSeriesID(p.name, p.labels)
654			ref := SeriesRef{Name: p.name, Labels: p.labels}
655	
656			// 同一采样位置无论值来自本批较早接受的点还是此前批次已写入的点，
657			// 都走同一条判定：转换后的 float64 相等即重复、成功忽略，不同即冲突、
658			// 整批拒绝。existing 是该位置当前生效的值，两种来源下语义一致。
659			if existing, ok := s.positionValue(seen, id, p.ts); ok {
660				if existing != p.value {
661					return nil, conflictAt(pos, ref, p.ts, existing, p.value)
662				}
663				// 等值重复：成功忽略。seen 记录的是生效值 existing 而不是本次
664				// 提交的 p.value：数值相等但表示不同（如已存 -0、本次提交 +0）时，
665				// 本批后续在同位置的冲突必须如实报告最先接受的值，
666				// 不能被这条被忽略的重复改写。
667				if seen[id] == nil {
668					seen[id] = map[int64]float64{}
669				}
670				seen[id][p.ts] = existing
671				continue
672			}
673	
674			added++
675			if seen[id] == nil {
676				seen[id] = map[int64]float64{}
677			}
678			seen[id][p.ts] = p.value
679			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
680		}
681	
682		// 全部采样点合法且无冲突，原子提交本批新增点。
683		for _, c := range commits {
684			sr := s.series[c.id]
685			if sr == nil {
686				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
687				s.series[c.id] = sr
688			}
689			sr.points[c.ts] = c.val
690		}
691	
692		return s.snapshot(added, len(items)-added), nil
693	}
694	
695	// positionValue 解析一个采样位置（序列身份 + 时间戳）当前生效的值：
696	// 本批已接受的值优先（含与已写入数据等值而被忽略的重复所登记的生效值），
697	// 其次是此前批次已成功写入的值；该位置没有任何数据时 ok 为 false。
698	// 重复与冲突判定只看这里返回的值，不再区分两种来源。
699	func (s *MetricStore) positionValue(seen map[seriesID]map[int64]float64, id seriesID, ts int64) (value float64, ok bool) {
700		if byTS, found := seen[id]; found {
701			if v, hit := byTS[ts]; hit {
702				return v, true
703			}
704		}
705		if sr, found := s.series[id]; found {
706			if v, hit := sr.points[ts]; hit {
707				return v, true
708			}
709		}
710		return 0, false
711	}
712	
713	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
714	func formatFloat(v float64) string {
715		return strconv.FormatFloat(v, 'g', -1, 64)
716	}
717	
718	type parsedQuery struct {
719		op     string
720		name   string
721		start  int64
722		end    int64
723		labels map[string]string
724	}
725	
726	// queryFromObject 严格解析查询对象并执行对应的只读操作：op 为 "query" 时
727	// 统计区间内点数与均值，为 "query_points" 时列出区间内采样明细。
728	// 成功返回非 nil 的 *QueryResult 或 *QueryPointsResult；失败返回 nil 与 *LineError。
729	func (s *MetricStore) queryFromObject(raw json.RawMessage) (any, *LineError) {
730		q, err := parseQuery(raw)
731		if err != nil {
732			return nil, &LineError{Status: "error", Error: err.Error()}
733		}
734		if q.start > q.end {
735			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
736				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
737		}
738		if q.op == "query_points" {
739			return s.runQueryPoints(q), nil
740		}
741		return s.runQuery(q), nil
742	}
743	
744	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
745	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
746	// op 只接受 "query"（区间点数与均值）与 "query_points"（区间采样明细），
747	// 两种操作共用同一套字段校验与区间规则。
748	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
749		var q parsedQuery
750		err := parseStrictObject(raw,
751			"each query must be a JSON object",
752			"unexpected content after the query object",
753			[]string{"op", "name", "start", "end"},
754			map[string]fieldReader{
755				"op": func(dec *json.Decoder) error {
756					t, err := dec.Token()
757					if err != nil {
758						return err
759					}
760					op, ok := t.(string)
761					if !ok {
762						return fmt.Errorf(`field "op" must be a string`)
763					}
764					if op != "query" && op != "query_points" {
765						return fmt.Errorf(`unknown op %q (only "query" and "query_points" are supported)`, op)
766					}
767					q.op = op
768					return nil
769				},
770				"name":  func(dec *json.Decoder) error { return readNameField(dec, &q.name) },
771				"start": func(dec *json.Decoder) error { return readInt64Field(dec, "start", &q.start) },
772				"end":   func(dec *json.Decoder) error { return readInt64Field(dec, "end", &q.end) },
773				"labels": func(dec *json.Decoder) error {
774					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
775				},
776			})
777		return q, err
778	}
779	
780	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
781	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
782	func labelsMatch(want, stored map[string]string) bool {
783		for k, v := range want {
784			got, ok := stored[k]
785			if !ok || got != v {
786				return false
787			}
788		}
789		return true
790	}
791	
792	// matchSeries 筛出名称精确匹配且标签子集命中的已存序列，供两种查询操作各自整理；
793	// 只读，不改变存储。
794	func (s *MetricStore) matchSeries(q parsedQuery) []*storedSeries {
795		matched := make([]*storedSeries, 0)
796		for _, sr := range s.series {
797			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
798				continue
799			}
800			matched = append(matched, sr)
801		}
802		return matched
803	}
804	
805	// runQuery 只读统计已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
806	// 序列身份的整理（标签副本、排序键值对、排列次序）与写入快照共用同一套
807	// organizeSeries 规则，只是入选范围不同：这里先按名称与标签条件筛出命中序列
808	// 再整理，不为无关指标承担展示准备；筛后剩余序列的相对次序因此与写入全量
809	// 结果一致。查询只返回每条序列的点数与均值，不构造采样明细列表（明细由
810	// query_points 操作提供）——单次遍历点表只做计数与精确有理数求和（计数与
811	// 均值都与点的排列次序无关）。区间内没有点的序列不列出，不补零值条目。
812	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
813		organized := organizeSeries(s.matchSeries(q))
814	
815		out := make([]QuerySeries, 0, len(organized))
816		for _, entry := range organized {
817			// 一次遍历直接统计：区间内点的个数与精确总和。不构造值切片、
818			// 不排序时间戳，避免为只返回 count/average 的查询承担采样明细展示。
819			// 求和在有理数上精确完成：与写入顺序、批次划分无关，正负大数抵消后的
820			// 小余量不会丢失，总和超出 float64 范围时均值仍然有限。
821			count := 0
822			sum := new(big.Rat)
823			r := new(big.Rat)
824			for ts, v := range entry.sr.points {
825				if ts < q.start || ts > q.end {
826					continue
827				}
828				count++
829				// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
830				sum.Add(sum, r.SetFloat64(v))
831			}
832			if count == 0 {
833				continue
834			}
835			sum.Quo(sum, r.SetInt64(int64(count)))
836			out = append(out, QuerySeries{
837				Name:   entry.ref.Name,
838				Labels: entry.ref.Labels,
839				Count:  count,
840				// 精确平均舍入到最近可表示 float64（正中取偶）；精确为零时返回 +0。
841				Average: ratToFloat64NearestEven(sum),
842			})
843		}
844		return &QueryResult{Status: "ok", Op: "query", Series: out}
845	}
846	
847	// runQueryPoints 只读列出已成功提交的采样明细：name 精确、标签子集、
848	// [start,end] 闭区间，与 runQuery 共用同一套序列筛选与 organizeSeries 整理
849	// 规则，因此序列排列次序与均值查询一致。每条命中序列保留完整指标名与完整
850	// 标签集合，points 按时间戳升序列出区间内的 timestamp 与 value，不附加
851	// count 或 average；区间内没有点的序列不列出，没有任何命中时 series 为
852	// 空数组。时间戳以 int64 比较与输出，保留整数精度；value 是实际存储的
853	// float64。查询只读，不改变采样值或写入计数。
854	func (s *MetricStore) runQueryPoints(q parsedQuery) *QueryPointsResult {
855		organized := organizeSeries(s.matchSeries(q))
856	
857		out := make([]QueryPointsSeries, 0, len(organized))
858		for _, entry := range organized {
859			points := seriesPointsInRange(entry.sr, q.start, q.end)
860			if len(points) == 0 {
861				continue
862			}
863			out = append(out, QueryPointsSeries{
864				Name:   entry.ref.Name,
865				Labels: entry.ref.Labels,
866				Points: points,
867			})
868		}
869		return &QueryPointsResult{Status: "ok", Op: "query_points", Series: out}
870	}
871	
872	// seriesPointsInRange 按 timestamp 升序返回一条已存序列在 [start,end] 闭区间
873	// 内的采样点，供采样明细查询展示。与 allSeriesPoints 一样返回新建切片与新建
874	// Point，调用方对结果的修改不影响存储；区别只在这里按区间过滤时间戳。
875	func seriesPointsInRange(sr *storedSeries, start, end int64) []Point {
876		tsList := make([]int64, 0, len(sr.points))
877		for ts := range sr.points {
878			if ts < start || ts > end {
879				continue
880			}
881			tsList = append(tsList, ts)
882		}
883		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
884		points := make([]Point, len(tsList))
885		for i, ts := range tsList {
886			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
887		}
888		return points
889	}
890	
891	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
892	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
893	func ratToFloat64NearestEven(x *big.Rat) float64 {
894		if x.Sign() == 0 {
895			return 0
896		}
897		num := new(big.Int).Set(x.Num())
898		den := x.Denom()
899		neg := num.Sign() < 0
900		if neg {
901			num.Neg(num)
902		}
903	
904		// e 满足 2^e <= num/den < 2^(e+1)。
905		e := floorLog2Rat(num, den)
906		var m *big.Int
907		scale := 0
908		if e >= -1022 {
909			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
910			scale = e - 52
911			m = roundScaledRatio(num, den, scale)
912			if m.BitLen() == 54 {
913				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
914				m.Rsh(m, 1)
915				scale++
916			}
917		} else {
918			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
919			scale = -1074
920			m = roundScaledRatio(num, den, scale)
921		}
922		// m < 2^53，可以精确放入 int64 与 float64。
923		f := math.Ldexp(float64(m.Int64()), scale)
924		if neg {
925			return -f
926		}
927		return f
928	}
929	
930	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
931	func floorLog2Rat(num, den *big.Int) int {
932		k := num.BitLen() - den.BitLen()
933		var t big.Int
934		if k >= 0 {
935			t.Lsh(den, uint(k))
936			if num.Cmp(&t) >= 0 {
937				return k
938			}
939			return k - 1
940		}
941		t.Lsh(num, uint(-k))
942		if t.Cmp(den) >= 0 {
943			return k
944		}
945		return k - 1
946	}
947	
948	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
949	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
950		n := new(big.Int).Set(num)
951		d := new(big.Int).Set(den)
952		if scale >= 0 {
953			d.Lsh(d, uint(scale))
954		} else {
955			n.Lsh(n, uint(-scale))
956		}
957		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
958		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
959		case 1:
960			q.Add(q, big.NewInt(1))
961		case 0:
962			if q.Bit(0) == 1 {
963				q.Add(q, big.NewInt(1))
964			}
965		}
966		return q
967	}
968	
969	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
970	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
971	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
972	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
973	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
974	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
975	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
976	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
977	func (r SeriesRef) String() string {
978		var b strings.Builder
979		b.WriteString(identityText(r.Name))
980		b.WriteByte('{')
981		for i, p := range sortedPairs(r.Labels) {
982			if i > 0 {
983				b.WriteByte(',')
984			}
985			b.WriteString(identityText(p.Key))
986			b.WriteByte('=')
987			b.WriteString(identityText(p.Value))
988		}
989		b.WriteByte('}')
990		return b.String()
991	}
992	
993	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
994	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
995	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
996	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
997	// 因此渲染结果不会把内容字符误读为标签边界。
998	func identityText(s string) string {
999		if s == "" || s != strings.TrimSpace(s) {
1000			return strconv.Quote(s)
1001		}
1002		for _, r := range s {
1003			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
1004				return strconv.Quote(s)
1005			}
1006		}
1007		return s
1008	}
1009	
1010	// organizedSeries 是结果整理中的一条序列：携带已存序列指针、
1011	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
1012	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
1013	// 整理好的键值对，供排序比较直接复用。写入快照与区间查询都经由
1014	// organizeSeries 得到这样的条目，区别只在入选的序列范围。
1015	type organizedSeries struct {
1016		sr    *storedSeries
1017		ref   SeriesRef
1018		pairs []labelPair
1019	}
1020	
1021	// seriesLess 是写入快照与区间查询共用的序列次序约定：先按指标名字符串
1022	// 字典序，同名再按标签键升序后的键值对逐对比较（先比键再比值，前一对
1023	// 相同才比下一对；较短集合是完整前缀时排前，无标签序列因此排在最前）。
1024	// 标签值按字符串比较（"10" 在 "2" 之前）。排序只看解析后的真实身份，
1025	// 与冲突原因里的展示文字、标签的输入次序无关。
1026	func seriesLess(a, b organizedSeries) bool {
1027		if a.ref.Name != b.ref.Name {
1028			return a.ref.Name < b.ref.Name
1029		}
1030		return compareLabelPairs(a.pairs, b.pairs) < 0
1031	}
1032	
1033	// organizeSeries 是两种成功结果共用的序列身份整理：对入选的每条已存序列
1034	// 复制独立的标签副本、预整理按键升序的键值对，并按 seriesLess 的统一次序
1035	// 排列。入选范围由调用方决定：写入快照传入全部已提交序列，两种区间查询只
1036	// 传入名称与标签条件命中的序列；它们因此遵循同一套整理规则而各自保留数据
1037	// 范围。每条序列的标签只在入选时整理一次：排序后的键值对随条目保留，sort
1038	// 的反复比较直接复用同一份结果，不会因一条序列参与多次比较而反复整理同一
1039	// 套标签。整理结果不复制采样点；写入快照的采样点选取与升序排列由
1040	// allSeriesPoints 完成，均值查询只在点表上计数与求和，采样明细查询由
1041	// seriesPointsInRange 按区间选取并升序排列。
1042	func organizeSeries(selected []*storedSeries) []organizedSeries {
1043		out := make([]organizedSeries, 0, len(selected))
1044		for _, sr := range selected {
1045			// 标签必须复制：成功结果是当次操作的独立记录，
1046			// 调用方修改结果标签不能改动已存序列的身份。
1047			labels := cloneLabels(sr.ref.Labels)
1048			out = append(out, organizedSeries{
1049				sr:    sr,
1050				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
1051				pairs: sortedPairs(labels),
1052			})
1053		}
1054		sort.Slice(out, func(i, j int) bool { return seriesLess(out[i], out[j]) })
1055		return out
1056	}
1057	
1058	// allSeriesPoints 按 timestamp 升序返回一条已存序列的全部采样点，数值与
1059	// 时间戳一一对应，供写入快照展示。返回的是新建切片与新建 Point，调用方对
1060	// 采样点的修改不影响存储，也不影响此前或此后取得的其他成功结果。均值查询
1061	// 不构造这样的明细列表，只在点表上计数与求和；采样明细查询的区间版本由
1062	// seriesPointsInRange 提供。
1063	func allSeriesPoints(sr *storedSeries) []Point {
1064		tsList := make([]int64, 0, len(sr.points))
1065		for ts := range sr.points {
1066			tsList = append(tsList, ts)
1067		}
1068		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
1069		points := make([]Point, len(tsList))
1070		for i, ts := range tsList {
1071			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
1072		}
1073		return points
1074	}
1075	
1076	// snapshot 生成按规范排序的全部序列视图：入选范围是全部已提交序列，
1077	// 身份整理与次序来自 organizeSeries，点排列来自 allSeriesPoints；
1078	// 两种区间查询共用同一套身份整理，各自只对命中序列统计均值或列出明细。
1079	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
1080		all := make([]*storedSeries, 0, len(s.series))
1081		for _, sr := range s.series {
1082			all = append(all, sr)
1083		}
1084		organized := organizeSeries(all)
1085		views := make([]SeriesView, 0, len(organized))
1086		for _, os := range organized {
1087			views = append(views, SeriesView{
1088				Name:   os.ref.Name,
1089				Labels: os.ref.Labels,
1090				Points: allSeriesPoints(os.sr),
1091			})
1092		}
1093		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
1094	}
1095

