105	// TestQueryPointsResultShape 锁定成功结果的 JSON 形状：op 为 query_points，
106	// 序列条目只有 name、labels、points（没有 count/average），点只有
107	// timestamp 与 value；无命中时 series 是空数组而不是 null。
108	func TestQueryPointsResultShape(t *testing.T) {
