240		}
241		assertPoints(t, res.Series[0], []Point{{Timestamp: 20, Value: 2}}, "host=h series in [15,25]")
242		assertPoints(t, res.Series[1], []Point{{Timestamp: 20, Value: 6}}, "zone=x series in [15,25]")
243	
244		// name 精确匹配：不同指标不返回。
245		res = mustQueryPoints(t, store, queryPointsAll("other", 0, 100))
246		if len(res.Series) != 1 || res.Series[0].Name != "other" {
247			t.Fatalf("other metric = %+v", res.Series)
248		}
249	}
250	
251	// TestQueryPointsInt64TimestampPrecision 范围判断与输出保留时间戳的整数
252	// 精度：2^53 与 2^53+1 是两个不同的采样位置，单点查询各自只列出该位置；
253	// int64 两个端点也能精确寻址。
254	func TestQueryPointsInt64TimestampPrecision(t *testing.T) {
255		store := NewMetricStore()
256		labels := map[string]string{"host": "a"}
257		// 非时间顺序写入：先 2^53+1 值 8，再 2^53 值 2。
258		mustOK(t, store, "["+
259			sample("cpu", tsTwoPow53Plus, 8, labels)+","+
260			sample("cpu", tsTwoPow53, 2, labels)+"]")
261	
262		res := mustQueryPoints(t, store, queryPointsLabels("cpu", tsTwoPow53, tsTwoPow53, labels))
263		assertPoints(t, res.Series[0], []Point{{Timestamp: tsTwoPow53, Value: 2}}, "only 2^53")
264		res = mustQueryPoints(t, store, queryPointsLabels("cpu", tsTwoPow53Plus, tsTwoPow53Plus, labels))
265		assertPoints(t, res.Series[0], []Point{{Timestamp: tsTwoPow53Plus, Value: 8}}, "only 2^53+1")
266		// 闭区间包含两者，按时间戳升序输出（与写入顺序相反）。
267		res = mustQueryPoints(t, store, queryPointsLabels("cpu", tsTwoPow53, tsTwoPow53Plus, labels))
268		assertPoints(t, res.Series[0], []Point{
269			{Timestamp: tsTwoPow53, Value: 2},
270			{Timestamp: tsTwoPow53Plus, Value: 8},
271		}, "both adjacent positions ascending")
272	
273		// int64 端点：MinInt64 与 MaxInt64 上的点可精确寻址，输出的时间戳整数不丢精度。
274		mustOK(t, store, "["+
275			sample("m", tsMaxInt64, 8, nil)+","+
276			sample("m", tsMinInt64, 2, nil)+"]")
277		res = mustQueryPoints(t, store, queryPointsAll("m", tsMinInt64, tsMaxInt64))
278		assertPoints(t, res.Series[0], []Point{
279			{Timestamp: tsMinInt64, Value: 2},
280			{Timestamp: tsMaxInt64, Value: 8},
281		}, "full int64 range")
282		raw := marshalCompact(t, res)
283		if !strings.Contains(raw, "9223372036854775807") || !strings.Contains(raw, "-9223372036854775808") {
284			t.Fatalf("int64 boundary timestamps must serialize exactly, got %s", raw)
285		}
286	}
287	
288	// TestQueryPointsStoredFloat64Values value 展示实际存储的 float64 值：
289	// 十进制写法不保留、只保留转换后的二进制值；特殊值 -0 与极大值原样呈现。
290	func TestQueryPointsStoredFloat64Values(t *testing.T) {
291		store := NewMetricStore()
292		mustOK(t, store, `[
293			{"name":"m","timestamp":1,"value":0.1},
294			{"name":"m","timestamp":2,"value":1.0000000000000002},
295			{"name":"m","timestamp":3,"value":1e308}
296		]`)
297		res := mustQueryPoints(t, store, queryPointsAll("m", 0, 10))
298		want := []Point{
299			{Timestamp: 1, Value: 0.1},
300			{Timestamp: 2, Value: 1.0000000000000002},
301			{Timestamp: 3, Value: 1e308},
302		}
303		assertPoints(t, res.Series[0], want, "stored float64 values")
304		raw := marshalCompact(t, res)
305		if !strings.Contains(raw, `"value":1e+308`) {
306			t.Fatalf("large value must serialize as stored float64, got %s", raw)
307		}
308	}
309	
310	// TestQueryPointsReadOnlyAndCommittedOnly query_points 只读取此前成功提交
311	// 的数据：失败批次回滚的点不可见，等值重复不新增点；查询本身不改变存储，
312	// 重复查询结果一致，随后的写入快照与均值查询保持原状。
313	func TestQueryPointsReadOnlyAndCommittedOnly(t *testing.T) {
314		store := NewMetricStore()
315		mustOK(t, store, `[{"name":"m","timestamp":10,"value":2}]`)
316		mustOK(t, store, `[{"name":"m","timestamp":20,"value":4}]`)
317	
318		baseline := func() {
319			t.Helper()
320			res := mustQueryPoints(t, store, queryPointsAll("m", 0, 100))
321			if len(res.Series) != 1 {
322				t.Fatalf("baseline series = %+v, want one", res.Series)
323			}
324			assertPoints(t, res.Series[0], []Point{
325				{Timestamp: 10, Value: 2},
326				{Timestamp: 20, Value: 4},
327			}, "baseline points")
328		}
329		baseline()
330	
331		// 失败批次整批回滚：其中任何点都不能被 query_points 看到。
332		mustFail(t, store, `[{"name":"m","timestamp":30,"value":8},{"name":"m","timestamp":10,"value":100}]`)
333		baseline()
334	
335		// 等值重复被忽略，不新增点。
336		mustOK(t, store, `[{"name":"m","timestamp":20,"value":4.0}]`)
337		baseline()
338	
339		// 查询不改变存储：重复查询一致，写入快照与均值查询结果不变。
340		res1 := mustQueryPoints(t, store, queryPointsAll("m", 0, 100))
341		res2 := mustQueryPoints(t, store, queryPointsAll("m", 0, 100))
342		if !reflect.DeepEqual(res1, res2) {
343			t.Fatalf("repeated query_points differs: %+v vs %+v", res1, res2)
344		}
345		snap := mustOK(t, store, `[]`)
346		if len(snap.Series) != 1 || len(snap.Series[0].Points) != 2 {
347			t.Fatalf("query_points mutated storage, snapshot = %+v", snap.Series)
348		}
349		qr := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100}`)
350		if len(qr.Series) != 1 || qr.Series[0].Count != 2 || qr.Series[0].Average != 3 {
351			t.Fatalf("query after query_points = %+v, want count 2 average 3", qr.Series)
352		}
353	}
354	
355	// TestQueryPointsFailuresFollowQueryConventions 输入校验与失败原因的选择
356	// 沿用 query 的约定：字段错误、缺字段、未知 op、倒置区间（指出实际边界）
357	// 都返回结构化错误，不带 index 与 conflict，也不返回 series；失败不改变存储。
358	func TestQueryPointsFailuresFollowQueryConventions(t *testing.T) {
359		store := NewMetricStore()
360		mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
361	
362		cases := []struct {
363			name string
364			line string
365			want string
366		}{
367			{"name wrong type", `{"op":"query_points","name":7,"start":0,"end":1}`, `field "name" must be a string`},
368			{"empty name", `{"op":"query_points","name":"","start":0,"end":1}`, `field "name" must be a non-empty string`},
369			{"start wrong type", `{"op":"query_points","name":"cpu","start":"0","end":1}`, `field "start" must be a JSON number`},
370			{"start not integer", `{"op":"query_points","name":"cpu","start":0.5,"end":1}`, `field "start"`},
371			{"end beyond int64", `{"op":"query_points","name":"cpu","start":0,"end":9223372036854775808}`,
372				`field "end"`},
373			{"missing end", `{"op":"query_points","name":"cpu","start":0}`, `missing required field "end"`},
374			{"missing op", `{"name":"cpu","start":0,"end":1}`, `missing required field "op"`},
375			{"unknown field", `{"op":"query_points","name":"cpu","start":0,"end":1,"extra":1}`, `unknown field "extra"`},
376			{"duplicate field", `{"op":"query_points","name":"cpu","start":0,"start":1,"end":2}`, `duplicate field "start"`},
377			{"labels wrong type", `{"op":"query_points","name":"cpu","start":0,"end":1,"labels":[]}`,
378				`field "labels" must be an object`},
379			{"duplicate label key", `{"op":"query_points","name":"cpu","start":0,"end":1,"labels":{"k":"a","k":"b"}}`,
380				`duplicate label key "k"`},
381			{"unknown op", `{"op":"ping","name":"cpu","start":0,"end":1}`, `unknown op "ping"`},
382			{"inverted range", `{"op":"query_points","name":"cpu","start":5000,"end":1000}`,
383				`invalid range: "start" must not be greater than "end" (5000 > 1000)`},
384			{"inverted range at extremes",
385				queryPointsAll("cpu", tsMaxInt64, tsMinInt64),
386				fmt.Sprintf("%d > %d", tsMaxInt64, tsMinInt64)},
387			{"trailing content", `{"op":"query_points","name":"cpu","start":0,"end":1} trailing`, "invalid JSON"},
388		}
389		for _, tc := range cases {
390			t.Run(tc.name, func(t *testing.T) {
391				lerr := mustQueryPointsFail(t, store, tc.line)
392				assertQueryError(t, lerr, tc.want)
393				// 失败结果没有 series、index 或 conflict。
394				m := marshalLineError(t, lerr)
395				for _, banned := range []string{"series", "index", "conflict"} {
396					if _, ok := m[banned]; ok {
397						t.Fatalf("query_points failure must not carry %q: %v", banned, m)
398					}
399				}
400			})
401		}
402	
403		// 所有失败之后，已存数据原样可见。
404		res := mustQueryPoints(t, store, queryPointsAll("cpu", 0, 2000))
405		if len(res.Series) != 1 {
406			t.Fatalf("stored data changed after failures: %+v", res.Series)
407		}
408		assertPoints(t, res.Series[0], []Point{{Timestamp: 1000, Value: 2}}, "baseline after failures")
409	}
410	
411	// TestQueryPointsViaProcessLine 统一入口对 query_points 对象返回非 nil 的
412	// *QueryPointsResult；失败仍是真正的 nil 结果。专用入口分工：QueryLine 只
413	// 执行 op "query"，QueryPointsLine 只执行 op "query_points"，交叉使用报错。
414	func TestQueryPointsViaProcessLine(t *testing.T) {
415		store := NewMetricStore()
416		mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
417	
418		r, lerr := store.ProcessLine(`{"op":"query_points","name":"cpu","start":0,"end":2000}`)
419		if lerr != nil || r == nil {
420			t.Fatalf("ProcessLine query_points: r=%v lerr=%+v", r, lerr)
421		}
422		qp, ok := r.(*QueryPointsResult)
423		if !ok {
424			t.Fatalf("ProcessLine query_points result type = %T, want *QueryPointsResult", r)
425		}
426		if qp.Op != "query_points" || len(qp.Series) != 1 {
427			t.Fatalf("ProcessLine query_points = %+v", qp)
428		}
429	
430		// 倒置区间经统一入口失败：真正的 nil 结果 + 结构化错误。
431		r, lerr = store.ProcessLine(`{"op":"query_points","name":"cpu","start":9,"end":1}`)
432		if r != nil || lerr == nil {
433			t.Fatalf("inverted query_points via ProcessLine: r=%v lerr=%+v", r, lerr)
434		}
435		if !strings.Contains(lerr.Error, "9 > 1") {
436			t.Fatalf("inverted range error = %q, want actual bounds", lerr.Error)
437		}
438	
439		// 专用入口交叉使用：op 与入口不匹配时给出明确错误，不返回另一类型的结果。
440		if _, lerr = store.QueryLine(`{"op":"query_points","name":"cpu","start":0,"end":1}`); lerr == nil {
441			t.Fatalf("QueryLine must reject op query_points")
442		}
443		if _, lerr = store.QueryPointsLine(`{"op":"query","name":"cpu","start":0,"end":1}`); lerr == nil {
444			t.Fatalf("QueryPointsLine must reject op query")
445		}
446	}
447	
448	// TestQueryPointsInterleavedWithWritesAndQueries 写入、均值查询与明细查询在
449	// 同一存储上交替进行：各自只读/原子写入的语义互不影响。
450	func TestQueryPointsInterleavedWithWritesAndQueries(t *testing.T) {
451		store := NewMetricStore()
452		mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
453	
454		res := mustQueryPoints(t, store, queryPointsLabels("cpu", 0, 3000, map[string]string{"host": "a"}))
455		assertPoints(t, res.Series[0], []Point{{Timestamp: 1000, Value: 2}}, "after first write")
456	
457		mustOK(t, store, `[{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}}]`)
458		res = mustQueryPoints(t, store, queryPointsLabels("cpu", 0, 3000, map[string]string{"host": "a"}))
459		assertPoints(t, res.Series[0], []Point{
460			{Timestamp: 1000, Value: 2},
461			{Timestamp: 2000, Value: 4},
462		}, "after second write")
463	
464		// 均值查询不受明细查询影响，仍按原语义统计。
465		qr := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"host":"a"}}`)
466		if len(qr.Series) != 1 || qr.Series[0].Count != 2 || qr.Series[0].Average != 3 {
467			t.Fatalf("query = %+v, want count 2 average 3", qr.Series)
468		}
469	}
