func TestQueryAverageExactZeroIsPositiveZero(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":1,"value":1e308},
		{"name":"m","timestamp":2,"value":-1e308},
		{"name":"m","timestamp":3,"value":5},
